class GeneAsAModelOfDiseaseAssociation(ModelToDiseaseAssociationMixin, GeneToDiseaseAssociation, EntityToDiseaseAssociationMixin):
    """
    An association in which a gene (e.g., a model-organism ortholog of a known disease gene) serves as a model of a human disease - for example, because mutants of the gene recapitulate core features of the disease.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'defining_slots': ['subject', 'predicate', 'object'],
         'from_schema': 'https://w3id.org/biolink/vocab/',
         'mixins': ['model to disease association mixin',
                    'entity to disease association mixin'],
         'slot_usage': {'subject': {'description': 'A gene that has a role in modeling '
                                                   'the disease. This may be a model '
                                                   'organism ortholog of a known '
                                                   'disease gene, or it may be a gene '
                                                   'whose mutants recapitulate core '
                                                   'features of the disease.',
                                    'name': 'subject',
                                    'range': 'gene or gene product'}}})

